onload = () => {
  const c = setTimeout(() => {
    document.body.classList.remove("not-loaded");
    clearTimeout(c);
  }, 1000);
};

// ===== Nhạc nền được nhúng sẵn trong code (vdlyer.mp3) =====
const MUSIC_SRC = "data:audio/mpeg;base64,";

const audio = new Audio(MUSIC_SRC);
audio.loop = true;
audio.volume = 0.8;

function startMusic() {
  return audio.play();
}

// 1. Thử phát ngay khi vào web
startMusic().catch(() => {
  // 2. Trình duyệt chặn tự phát -> phát ngay ở lần tương tác đầu tiên
  const events = ["click", "touchstart", "keydown", "wheel", "mousemove"];
  const unlock = () => {
    startMusic()
      .then(() => events.forEach((e) => removeEventListener(e, unlock)))
      .catch(() => {});
  };
  events.forEach((e) => addEventListener(e, unlock, { passive: true }));
});
